// ===========================================================================
// Фикстура §6.5: движущаяся кинематическая платформа.
//
// Платформа живёт скоростью из $.store: тест задаёт её сам
// (`liftVX`/`liftVY`, px/с), поэтому подъём, разворот, остановка и «платформа
// уехала» воспроизводятся покадрово и без гонки с автоматикой фикстуры.
// Трение платформы 0.05: перенос обязан давать контроллер (carryVelocity), а
// не трение Box2D.
// ===========================================================================

$.ready(() => {
    $.world.gravity(0, 1800).color('#101820')
        .bounds(-500, -1500, 4000, 4000, { solid: false });

    // Платформа: 200x20, верх y = 390.
    $('<wall>', { id: 'lift' }).at(1000, 400).size(200, 20)
        .attr({ friction: 0.05 }).body('kinematic').appendTo($.world);

    // Наездник: 26x30, центр на верхней грани (390 - 15 = 375).
    // Клавиша прыжка своя (q): общие Space из соседних тестов его не сбивают.
    $('<player>', { id: 'rider' }).at(1000, 360).size(26, 30)
        .health(100).controls({ axis: 'both', jump: 'q' })
        .attr({ friction: 0.05 })
        .collision(26, 30).appendTo($.world);

    $.store.set('liftVX', 0);
    $.store.set('liftVY', 0);
});

// Скорость кинематического тела живёт один кадр: задаём её каждый кадр.
$.update(() => {
    const lift = $('#lift');
    if (!lift.length) return;
    lift.velocity($.store.get('liftVX', 0) || 0, $.store.get('liftVY', 0) || 0);
});
